(function(){
  if(window.__growthV8)return;window.__growthV8=true;
  var v8key='xhs-growth-os-v8';var v8={metric:'曝光量',generated:null};try{v8=Object.assign(v8,JSON.parse(localStorage.getItem(v8key)||'null')||{})}catch(e){}
  function save(){try{localStorage.setItem(v8key,JSON.stringify(v8))}catch(e){}}
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function css(){if(document.querySelector('link[data-growth-v8]'))return;var l=document.createElement('link');l.rel='stylesheet';l.href='product-v8.css';l.dataset.growthV8='1';document.head.appendChild(l)}
  function addNav(){var nav=$('#nav');if(!nav||nav.querySelector('[data-v8-view="create"]'))return;var item=document.createElement('button');item.className='nav-item';item.dataset.v8View='create';item.innerHTML='<span style="font-size:18px;width:18px;text-align:center">✦</span><span class="nav-text">AI 创作</span>';var content=nav.querySelector('[data-view="content"]');if(content)content.insertAdjacentElement('afterend',item);else nav.appendChild(item)}
  function setNav(view){$$('.nav-item').forEach(function(b){b.classList.toggle('active',b.dataset.view===view||b.dataset.v8View===view)})}
  function createPage(){app.view='create';setNav('create');var main=$('#main');main.innerHTML='<div class="eyebrow"><span></span>AI 创作工作台 · 基于账号数据生成</div><div class="page-heading"><div><h1>AI 创作</h1><p>把运营洞察转成可以直接发布的内容草稿。</p></div><button class="secondary" data-v8-create-task>从任务开始</button></div><div class="v8-create"><section class="card"><div class="card-heading"><h2>创作 brief</h2><span class="tag medium">AI 辅助</span></div><label class="v8-form-label">内容目标<select id="v8-goal"><option>提升收藏</option><option>提升评论</option><option>扩大曝光</option><option>承接转化</option></select></label><div class="v8-form-row"><label class="v8-form-label">内容类型<select id="v8-type"><option>教程型内容</option><option>运营复盘</option><option>生活方式</option><option>个人观点</option></select></label><label class="v8-form-label">语气风格<select id="v8-tone"><option>清晰专业</option><option>真实分享</option><option>轻松口语</option><option>故事感</option></select></label></div><label class="v8-form-label">主题或关键词<input id="v8-topic" placeholder="例如：普通人如何开始做个人 IP"/></label><label class="v8-form-label">补充素材<textarea id="v8-material" placeholder="粘贴你的案例、数据、观点或产品信息…"></textarea></label><button class="primary v8-generate" data-v8-generate>✦ 生成内容草稿</button></section><section class="card"><div class="card-heading"><h2>生成结果</h2><span class="stats-note">会引用当前账号数据</span></div><div id="v8-output"><div class="v6-empty-state"><div class="empty-icon">✦</div><h3>准备好开始创作</h3><p>输入一个主题，AI 会结合教程类内容的表现，为你生成标题、正文结构、互动问题和标签。</p></div></div></section></div><section class="card v8-decision-card"><div class="card-heading"><h2>AI 创作建议</h2><button class="text-button" data-v8-open-ai>让 AI 运营总监解释 ›</button></div><div class="v8-decision-list"><div class="v8-decision"><span class="decision-index">1</span><span><b>延续教程型内容</b><p>收藏率比账号平均高 36%，优先选择“方法 + 结果”的结构。</p></span></div><div class="v8-decision"><span class="decision-index">2</span><span><b>在结尾加一个问题</b><p>评论率最近下降，建议用一个具体问题打开讨论。</p></span></div></div></section>';bindCreate()}
  function bindCreate(){document.querySelector('[data-v8-generate]')?.addEventListener('click',function(){var topic=$('#v8-topic').value.trim()||'普通人如何开始做个人 IP';var type=$('#v8-type').value;var goal=$('#v8-goal').value;v8.generated={topic:topic,type:type,goal:goal};save();$('#v8-output').innerHTML='<div class="v8-ai-output"><h3>'+esc(topic)+'：从 0 到 1 的可执行方法</h3><p>结合你最近教程型内容表现，建议用具体步骤开头，用一个真实结果收尾。</p><div class="output-block"><b>标题备选</b><span>1. 普通人如何开始做个人 IP？我用 3 步跑通第一篇内容<br>2. 没有定位也能开始：个人 IP 的最小行动清单<br>3. 从 0 到 1 做个人 IP，我会先做这 3 件事</span></div><div class="output-block"><b>正文结构</b><span>先讲一个真实困境 → 给出 3 个步骤 → 分享一个数据结果 → 留下具体问题引导评论</span></div><div class="output-block"><b>互动问题与标签</b><span>你现在最卡在哪一步？　#个人IP #内容运营 #小红书运营</span></div><div class="v8-output-actions"><button class="secondary" data-v8-save-draft>保存为草稿</button><button class="primary" data-v8-create-publish-task>创建发布任务</button></div></div>'});document.querySelector('[data-v8-create-task]')?.addEventListener('click',function(){taskDialog('发布一篇教程型内容')});document.querySelector('[data-v8-open-ai]')?.addEventListener('click',function(){openAI();setTimeout(function(){if(typeof growthAiMessage==='function')growthAiMessage('为什么教程型内容值得继续做？','AI 创作 · 教程型内容')},40)});}
  function createOutputHandler(e){if(e.target.closest('[data-v8-save-draft]')){var title=v8.generated?v8.generated.topic:'AI 创作草稿';app.notes.unshift([title,'运营经验','今天','草稿','—','—']);saveApp();toast('创作草稿已保存');go('content')}if(e.target.closest('[data-v8-create-publish-task]')){taskDialog('发布：'+(v8.generated?v8.generated.topic:'教程型内容'))}}
  function dashboardContribution(){if(app.view!=='dashboard'||$('#v8-contribution'))return;var main=$('#main');var card=document.createElement('section');card.id='v8-contribution';card.className='card v8-contribution';var notes=app.notes.slice(0,5);var max=Math.max.apply(null,notes.map(function(n){return parseInt(String(n[4]).replace(/,/g,''))||0}));card.innerHTML='<div class="card-heading"><h2>内容贡献排行</h2><button class="text-button" data-v8-ranking-ai>让 AI 解释贡献 ›</button></div><div class="v8-contribution-row" style="color:var(--weak);font-size:9px"><span></span><span>内容</span><span>曝光贡献</span><span>数值</span></div>'+notes.map(function(n,i){var value=parseInt(String(n[4]).replace(/,/g,''))||0;return '<div class="v8-contribution-row"><span class="v8-contribution-rank">'+(i+1)+'</span><span class="v8-contribution-title">'+esc(n[0])+'</span><span class="v8-bar"><i style="width:'+Math.max(4,Math.round(value/max*100))+'%"></i></span><span class="v8-contribution-value">'+esc(n[4])+'</span></div>'}).join('');var bottom=$('#main .bottom-grid');if(bottom)bottom.insertAdjacentElement('afterend',card)}
  function proactiveDecision(){if(app.view!=='dashboard'||$('#v8-decision'))return;var main=$('#main');var card=document.createElement('section');card.id='v8-decision';card.className='card v8-decision-card';card.innerHTML='<div class="card-heading"><h2>AI 今日决策</h2><button class="text-button" data-v8-run-all>执行全部建议 ›</button></div><div class="v8-decision-list"><div class="v8-decision"><span class="decision-index">A</span><span><b>先做高确定性增长动作</b><p>发布 1 篇教程型内容，并把评论区问题整理成下一篇选题。</p></span><button class="text-button" data-v8-decision-task>创建任务</button></div><div class="v8-decision"><span class="decision-index">B</span><span><b>修复互动率异常</b><p>最近 3 篇评论率下降，优先加一个具体问题和回复动作。</p></span><button class="text-button" data-v8-decision-ai>解释原因</button></div></div>';var banner=$('#main .insight-banner');if(banner)banner.insertAdjacentElement('afterend',card)}
  function enhanceIdeas(){if(app.view!=='ideas')return;var main=$('#main');if(!main.querySelector('.v8-ideas-toolbar')){var heading=main.querySelector('.page-heading');var bar=document.createElement('div');bar.className='v8-ideas-toolbar';bar.innerHTML='<input class="v8-ideas-search" placeholder="搜索灵感、主题或分类…"><select class="filter"><option>全部分类</option><option>教程</option><option>运营经验</option><option>生活方式</option></select>';if(heading)heading.insertAdjacentElement('afterend',bar)}main.querySelectorAll('.idea-card').forEach(function(card,i){if(card.querySelector('.v8-idea-actions'))return;var action=document.createElement('div');action.className='v8-idea-actions';action.innerHTML='<button data-v8-idea-task="'+i+'">转成任务</button><button data-v8-idea-ai="'+i+'">AI 扩展</button>';card.appendChild(action)});}
  function enhance(){css();addNav();if(app.view==='create')return;dashboardContribution();proactiveDecision();enhanceIdeas()}
  document.addEventListener('click',function(e){var create=e.target.closest('[data-v8-view]');if(create){e.preventDefault();createPage();return}var metricTab=e.target.closest('.chart-controls .tabs button');if(metricTab){v8.metric=metricTab.textContent.trim();save();var foot=document.querySelector('.chart-footnote');if(foot)foot.innerHTML='<i></i>'+esc(v8.metric)+' · '+stateRangeLabel()+' · 环比 +23.1%';toast('趋势指标已切换为 '+v8.metric);return}var rank=e.target.closest('[data-v8-ranking-ai]');if(rank){openAI();setTimeout(function(){if(typeof growthAiMessage==='function')growthAiMessage('请解释近期内容贡献排行，并告诉我下一周应该复制什么。','内容贡献排行')},40);return}var run=e.target.closest('[data-v8-run-all]');if(run){app.tasks.unshift(['执行 AI 今日决策','高','待完成','今天','AI 推荐']);saveApp();toast('已生成今日决策任务');go('tasks');return}var dt=e.target.closest('[data-v8-decision-task]');if(dt){taskDialog('发布一篇教程型内容');return}var dai=e.target.closest('[data-v8-decision-ai]');if(dai){openAI();setTimeout(function(){if(typeof growthAiMessage==='function')growthAiMessage('为什么最近评论率下降？','AI 今日决策 · 互动率异常')},40);return}var it=e.target.closest('[data-v8-idea-task]');if(it){var idea=app.ideas[+it.dataset.v8IdeaTask];taskDialog('完善灵感：'+(idea?idea[1]:'内容选题'));return}var ia=e.target.closest('[data-v8-idea-ai]');if(ia){var item=app.ideas[+ia.dataset.v8IdeaAi];openAI();setTimeout(function(){if(typeof growthAiMessage==='function')growthAiMessage('请把这个灵感扩展成一个可发布的选题、标题和内容结构。',item?item[1]:'灵感库')},40);return}var saveDraft=e.target.closest('[data-v8-save-draft]');if(saveDraft)createOutputHandler(e)},true);function stateRangeLabel(){return v8.dateRange||'近 7 天'}document.addEventListener('input',function(e){if(!e.target.classList.contains('v8-ideas-search'))return;var val=e.target.value.toLowerCase();$$('.idea-card').forEach(function(c){c.hidden=!!val&&c.textContent.toLowerCase().indexOf(val)<0})});var observer=new MutationObserver(function(){clearTimeout(window.__v8timer);window.__v8timer=setTimeout(enhance,60)});observer.observe(document.getElementById('main')||document.body,{childList:true,subtree:true});setTimeout(enhance,80)
})();
